def compute(vars):
    securities = vars["v1"]
    exercise_price = vars["v2"]
    total_value_usd = securities * exercise_price
    value_millions = total_value_usd / 1_000_000

    return {
        "value": value_millions,
        "trace": {
            "securities": securities,
            "exercise_price_usd_per_share": exercise_price,
            "total_value_usd": total_value_usd,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
